import { useCallback } from 'react';
import Sound from 'react-native-sound';

// Initialize sounds
Sound.setCategory('Playback');

// Preload sounds
const soundEffects: { [key: string]: Sound } = {};

// Define sound paths
const soundPaths: { [key: string]: string } = {
  move: 'move.mp3',
  win: 'win.mp3',
  error: 'error.mp3',
  hint: 'hint.mp3',
  click: 'click.mp3',
};

// Load sounds
Object.entries(soundPaths).forEach(([key, path]) => {
  soundEffects[key] = new Sound(path, Sound.MAIN_BUNDLE, (error) => {
    if (error) {
      console.log(`Failed to load the sound ${key}:`, error);
      return;
    }
  });
});

type SoundType = 'move' | 'win' | 'error' | 'hint' | 'click';

const useSound = () => {
  const playSound = useCallback((type: SoundType) => {
    const sound = soundEffects[type];
    if (sound) {
      sound.stop(() => {
        sound.play();
      });
    }
  }, []);

  return { playSound };
};

export default useSound;
